INSERT INTO repo_esd_objectives (esd_objective_id, domain, objective_no, text, status) VALUES ('ESD_SDG01_COG_01', 'Cognitive', '1', 'The learner understands the concepts of extreme and relative poverty and is able to critically reflect on their underlying cultural and normative assumptions and practices.', 'Active'), ('ESD_SDG01_COG_02', 'Cognitive', '2', 'The learner knows about the local, national and global distribution of extreme poverty and extreme wealth.', 'Active'), ('ESD_SDG01_COG_03', 'Cognitive', '3', 'The learner knows about causes and impacts of poverty such as unequal distribution of resources and power, colonization, conflicts, disasters caused by natural hazards and other climate change-induced impacts, environmental degradation and technological disasters, and the lack of social protection systems and measures.', 'Active'), ('ESD_SDG01_COG_04', 'Cognitive', '4', 'The learner understands how extremes of poverty and extremes of wealth affect basic human rights and needs.', 'Active'), ('ESD_SDG01_COG_05', 'Cognitive', '5', 'The learner knows about poverty reduction strategies and measures and is able to distinguish between deficit-based and strength-based approaches to addressing poverty.', 'Active'), ('ESD_SDG01_SOC_01', 'Socio-emotional', '1', 'The learner is able to collaborate with others to empower individuals and communities to affect change in the distribution of power and resources in the community and beyond.', 'Active'), ('ESD_SDG01_SOC_02', 'Socio-emotional', '2', 'The learner is able to raise awareness about extremes of poverty and wealth and encourage dialogue about solutions.', 'Active'), ('ESD_SDG01_SOC_03', 'Socio-emotional', '3', 'The learner is able to show sensitivity to the issues of poverty as well as empathy and solidarity with poor people and those in vulnerable situations.', 'Active'), ('ESD_SDG01_SOC_04', 'Socio-emotional', '4', 'The learner is able to identify their personal experiences and biases with respect to poverty.', 'Active'), ('ESD_SDG01_SOC_05', 'Socio-emotional', '5', 'The learner is able to reflect critically on their own role in maintaining global structures of inequality.', 'Active'), ('ESD_SDG01_BEH_01', 'Behavioural', '1', 'The learner is able to plan, implement, evaluate and replicate activities that contribute to poverty reduction.', 'Active'), ('ESD_SDG01_BEH_02', 'Behavioural', '2', 'The learner is able to publicly demand and support the development and integration of policies that promote social and economic justice, risk reduction strategies and poverty eradication actions.', 'Active'), ('ESD_SDG01_BEH_03', 'Behavioural', '3', 'The learner is able to evaluate, participate in and influence decision-making related to management strategies of local, national and international enterprises concerning poverty generation and eradication.', 'Active'), ('ESD_SDG01_BEH_04', 'Behavioural', '4', 'The learner is able to include poverty reduction, social justice and anti-corruption considerations in their consumption activities.', 'Active'), ('ESD_SDG01_BEH_05', 'Behavioural', '5', 'The learner is able to propose solutions to address systemic problems related to poverty.', 'Active'), ('ESD_SDG02_COG_01', 'Cognitive', '1', 'The learner knows about hunger and malnutrition and their main physical and psychological effects on human life, and about specific vulnerable groups.', 'Active'), ('ESD_SDG02_COG_02', 'Cognitive', '2', 'The learner knows about the amount and distribution of hunger and malnutrition locally, nationally and globally, currently as well as historically.', 'Active'), ('ESD_SDG02_COG_03', 'Cognitive', '3', 'The learner knows the main drivers and root causes for hunger at the individual, local, national and global level.', 'Active'), ('ESD_SDG02_COG_04', 'Cognitive', '4', 'The learner knows principles of sustainable agriculture and understands the need for legal rights to have land and property as necessary conditions to promote it.', 'Active'), ('ESD_SDG02_COG_05', 'Cognitive', '5', 'The learner understands the need for sustainable agriculture to combat hunger and malnutrition worldwide and knows about other strategies to combat hunger, malnutrition and poor diets.', 'Active'), ('ESD_SDG02_SOC_01', 'Socio-emotional', '1', 'The learner is able to communicate on the issues and connections between combating hunger and promoting sustainable agriculture and improved nutrition.', 'Active'), ('ESD_SDG02_SOC_02', 'Socio-emotional', '2', 'The learner is able to collaborate with others to encourage and to empower them to combat hunger and to promote sustainable agriculture and improved nutrition.', 'Active'), ('ESD_SDG02_SOC_03', 'Socio-emotional', '3', 'The learner is able to create a vision for a world without hunger and malnutrition.', 'Active'), ('ESD_SDG02_SOC_04', 'Socio-emotional', '4', 'The learner is able to reflect on their own values and deal with diverging values, attitudes and strategies in relation to combating hunger and malnutrition and promoting sustainable agriculture.', 'Active'), ('ESD_SDG02_SOC_05', 'Socio-emotional', '5', 'The learner is able to feel empathy, responsibility and solidarity for and with people suffering from hunger and malnutrition.', 'Active'), ('ESD_SDG02_BEH_01', 'Behavioural', '1', 'The learner is able to evaluate and implement actions personally and locally to combat hunger and to promote sustainable agriculture.', 'Active'), ('ESD_SDG02_BEH_02', 'Behavioural', '2', 'The learner is able to evaluate, participate in and influence decision-making related to public policies concerning the combat against hunger and malnutrition and the promotion of sustainable agriculture.', 'Active'), ('ESD_SDG02_BEH_03', 'Behavioural', '3', 'The learner is able to evaluate, participate in and influence decision-making related to management strategies of local, national and international enterprises concerning the combat against hunger and malnutrition and the promotion of sustainable agriculture.', 'Active'), ('ESD_SDG02_BEH_04', 'Behavioural', '4', 'The learner is able to take on critically their role as an active global citizen in the challenge of combating hunger.', 'Active'), ('ESD_SDG02_BEH_05', 'Behavioural', '5', 'The learner is able to change their production and consumption practices in order to contribute to the combat against hunger and the promotion of sustainable agriculture.', 'Active'), ('ESD_SDG03_COG_01', 'Cognitive', '1', 'The learner knows conceptions of health, hygiene and well-being and can critically reflect on them, including an understanding of the importance of gender in health and well-being.', 'Active'), ('ESD_SDG03_COG_02', 'Cognitive', '2', 'The learner knows facts and figures about the most severe communicable and non-communicable diseases, and the most vulnerable groups and regions concerning illness, disease and premature death.', 'Active'), ('ESD_SDG03_COG_03', 'Cognitive', '3', 'The learner understands the socio-political-economic dimensions of health and well-being and knows about the effects of advertising and about strategies to promote health and well-being.', 'Active'), ('ESD_SDG03_COG_04', 'Cognitive', '4', 'The learner understands the importance of mental health. The learner understands the negative impacts of behaviours like xenophobia, discrimination and bullying on mental health and emotional well-being and how addictions to alcohol, tobacco or other drugs cause harm to health and well-being.', 'Active'), ('ESD_SDG03_COG_05', 'Cognitive', '5', 'The learner knows relevant prevention strategies to foster positive physical and mental health and well-being, including sexual and reproductive health and information as well as early warning and risk reduction.', 'Active'), ('ESD_SDG03_SOC_01', 'Socio-emotional', '1', 'The learner is able to interact with people suffering from illnesses, and feel empathy for their situation and feelings.', 'Active'), ('ESD_SDG03_SOC_02', 'Socio-emotional', '2', 'The learner is able to communicate about issues of health, including sexual and reproductive health, and well-being, especially to argue in favour of prevention strategies to promote health and well-being.', 'Active'), ('ESD_SDG03_SOC_03', 'Socio-emotional', '3', 'The learner is able to encourage others to decide and act in favour of promoting health and well-being for all.', 'Active'), ('ESD_SDG03_SOC_04', 'Socio-emotional', '4', 'The learner is able to create a holistic understanding of a life of health and well-being, and to clarify related values, beliefs and attitudes.', 'Active'), ('ESD_SDG03_SOC_05', 'Socio-emotional', '5', 'The learner is able to develop a personal commitment to promoting health and well-being for themselves, their family and others, including considering volunteer or professional work in health and social care.', 'Active'), ('ESD_SDG03_BEH_01', 'Behavioural', '1', 'The learner is able to include health promoting behaviours in their daily routines.', 'Active'), ('ESD_SDG03_BEH_02', 'Behavioural', '2', 'The learner is able to plan, implement, evaluate and replicate strategies that promote health, including sexual and reproductive health, and well-being for themselves, their families and others.', 'Active'), ('ESD_SDG03_BEH_03', 'Behavioural', '3', 'The learner has the capacity to perceive when others need help and to seek help for themselves and others.', 'Active'), ('ESD_SDG03_BEH_04', 'Behavioural', '4', 'The learner is able to publicly demand and support the development of policies promoting health and well-being.', 'Active'), ('ESD_SDG03_BEH_05', 'Behavioural', '5', 'The learner is able to propose ways to address possible conflicts between the public interest in offering medicine at affordable prices and private interests within the pharmaceutical industry.', 'Active'), ('ESD_SDG04_COG_01', 'Cognitive', '1', 'The learner understands the important role of education and lifelong learning opportunities for all (formal, non-formal and informal learning) as main drivers of sustainable development, for improving people’s lives and in achieving the SDGs.', 'Active'), ('ESD_SDG04_COG_02', 'Cognitive', '2', 'The learner understands education as a public good, a global common good, a fundamental human right and a basis for guaranteeing the realization of other rights.', 'Active'), ('ESD_SDG04_COG_03', 'Cognitive', '3', 'The learner knows about inequality in access to and attainment of education, particularly between girls and boys and in rural areas, and about reasons for a lack of equitable access to quality education and lifelong learning opportunities.', 'Active'), ('ESD_SDG04_COG_04', 'Cognitive', '4', 'The learner understands the important role of culture in achieving sustainability.', 'Active'), ('ESD_SDG04_COG_05', 'Cognitive', '5', 'The learner understands that education can help create a more sustainable, equitable and peaceful world.', 'Active') ON CONFLICT DO NOTHING;